    if DIFF > 0:
        normalized_diff = DIFF / max_diff
    else:
        normalized_diff = 0.0

    # Compute urgency based on available space ratio
    if EMP == 0:
        urgency = 2.2
    elif EMP < SH / 3:
        urgency = 1.8
    elif EMP < SH / 2:
        urgency = 1.5
    else:
